INSERT INTO Article VALUES
(1, '關於我們', '<p style="text-indent: 0px; text-align: start;">Lets 菓是一家充滿責任感的果乾製造商，始終將消費者的健康和安心放在首位。我們以嚴謹的標準和匠心精神，為您帶來無添加、純天然的美味果乾。</p><p style="text-indent: 0px; text-align: start;">嚴選水果：我們精心挑選品質優良的水果，來源可靠，確保提供給您最好的原料。</p>', '2022-04-16 13:57:42', NULL, 0, 'https://i.imgur.com/SgQQNNu.png', 'Mark KU', 1, 48, 1),
(2, '嚴選水果', '<p style="text-indent: 0px; text-align: start;">Lets 菓嚴選為您呈現台灣在地水果的美味！我們每日親自前往青果市場挑選新鮮水果，經過細心清洗、切片後，進行10-12小時以上的低溫烘培。</p>', '2022-04-17 13:57:02', NULL, 0, 'https://i.imgur.com/6Trdqpk.jpeg', 'Mark Ku', 1, 42, 1),
(3, '包裝方式', '<p>包裝選擇<br>Lets 菓提供兩種環保又實用的包裝方式：</p>', '2022-04-17 13:57:33', NULL, 0, 'https://i.imgur.com/9RPbo9x.jpg', 'Mark Ku', 1, 84, 1),
(4, '低溫烘培12小時', '<p style="text-indent: 0px; text-align: start;">讓Lets菓嚴選帶您品味台灣在地水果的絕美滋味！每天，我們親自走訪青果市場，精挑細選新鮮水果。</p>', '2023-05-06 12:48:22', NULL, 0, 'https://i.imgur.com/Nncq6pB.jpg', 'Mark Ku', 1, 186, 1),
(5, '退換貨政策', '<p><span style="font-size: 16px;">lets菓，非常重視消費者權益，依據消費者保護法規定，所有網購消費者均享有商品到貨七天鑑賞期（猶豫期）之權益。</span></p>', '2023-05-12 14:33:11', NULL, 0, 'https://i.imgur.com/mz3Faf9.jpeg', 'Rabbit編', 1, 50, 0);

